#include <stdio.h>

#define PROCESSES 3
#define QUANTUM 2

int main() {
    int remaining[PROCESSES] = {4, 1, 3};
    int time = 0, done = 0;
    while (done < PROCESSES) {
        for (int i = 0; i < PROCESSES; i++) {
            if (remaining[i] > 0) {
                int slice = remaining[i] < QUANTUM ? remaining[i] : QUANTUM;
                time += slice;
                remaining[i] -= slice;
                if (remaining[i] == 0) {
                    printf("P%d done at %d\n", i + 1, time);
                    done++;
                }
            }
        }
    }
    return 0;
}
